static z_t7336_t z_io_stat(z_t59_t path) {
    z_t7336_t result = {0};
    z_t7328_t fs = {0};
#if defined(_WIN32)
    int e = z_io_win_stat(path, 1, &fs);
    int rc = e == 0 ? 0 : -1;
#else
    char* path_cstr = z_sv_to_cstr(path);
    struct stat sb;
    int rc = stat(path_cstr, &sb);
    int e = errno;
    free(path_cstr);
    if (rc == 0) z_io_fill_filestat(&fs, &sb);
#endif
    if (rc != 0) {
        z_t835_t* boxed = (z_t835_t*)z_xmalloc(sizeof(z_t835_t));
        *boxed = z_io_os_error(e);
        result.tag = Z_T7336_TAG_0;
        result.data = boxed;
        return result;
    }
    z_t7328_t* boxed = (z_t7328_t*)z_xmalloc(sizeof(z_t7328_t));
    *boxed = fs;
    result.tag = Z_T7336_TAG_1;
    result.data = boxed;
    return result;
}


