static const z_t6267_t _zag1693 = { { .data = "chan_send", .size = 9 }, { .length = 1, .data = _zag1691 }, { .length = 6, .data = _zag1692 }, { .data = "/* move the value at `value` in, waiting while the ring is full; false, the\n   value destroyed here, once the Receiver is gone */\nstatic bool z_chan_send(z_chan* b, void* value) {\n    z_mutex_lock(&b->m);\n    while (b->receiverAlive && b->cap != 0 && b->len == b->cap) z_cond_wait(&b->notFull, &b->m);\n    if (!b->receiverAlive) {\n        z_mutex_unlock(&b->m);\n        b->destroyElem(value);\n        return false;\n    }\n    if (b->len == b->size) z_chan_grow(b);\n    memcpy(b->ring + ((b->head + b->len) % b->size) * b->elemSize, value, b->elemSize);\n    b->len++;\n    z_cond_signal(&b->notEmpty);\n    z_mutex_unlock(&b->m);\n    return true;\n}", .size = 644 } };
